# Shared PNG font and pixel frames. Assets generated by Python.
module REPixelUI
  ROOT = "Plugins/00 RE Visual Core/assets/python"
  WIDTHS = File.read("#{ROOT}/font_widths.txt").split(",").map(&:to_i)
  PAPER = [245, 235, 208]
  INK = [15, 32, 59]
  GOLD = [226, 180, 88]
  NAVY = [8, 24, 49]
  @images = {}

  def self.image(name)
    cached = @images[name]
    @images[name] = Bitmap.new("#{ROOT}/#{name}.png") if !cached || cached.disposed?
    @images[name]
  end

  def self.scale(size)
    size >= 24 ? 2 : 1
  end

  def self.code(char)
    value = char.ord
    return value if value.between?(32, 255)
    return 62 if char == "\u2192"
    return 60 if char == "\u2190"
    return 77 if char == "\u2642"
    return 70 if char == "\u2640"
    return 42 if char == "\u2605"
    return 43 if char == "\u2713"
    return 45 if ["\u2014", "\u2013"].include?(char)
    63
  end

  def self.width(text, size = 16)
    text.to_s.each_char.sum { |char| WIDTHS[code(char) - 32] * scale(size) }
  end

  def self.fit(text, maximum, size = 16)
    return "" if maximum <= 0
    label = text.to_s
    return label if width(label, size) <= maximum
    suffix = "..."
    suffix = suffix[0...-1] while !suffix.empty? && width(suffix, size) > maximum
    label = label[0...-1] while !label.empty? && width(label + suffix, size) > maximum
    label + suffix
  end

  def self.wrap(text, maximum, size = 16)
    return [""] if maximum <= 0
    lines = []
    text.to_s.split("\n", -1).each do |paragraph|
      line = ""
      paragraph.split.each do |word|
        # Split unbroken words rather than allowing a glyph outside the panel.
        while width(word, size) > maximum
          lines << line unless line.empty?
          line = ""
          part = ""
          while !word.empty? && width(part + word[0], size) <= maximum
            part << word[0]; word = word[1..-1]
          end
          if part.empty?
            # A glyph wider than the entire panel cannot be drawn safely.
            # Consume it so the loop advances even on very narrow layouts.
            word = word[1..-1]
            next
          end
          lines << part
        end
        test = line.empty? ? word : "#{line} #{word}"
        if width(test, size) > maximum && !line.empty?
          lines << line; line = word
        else
          line = test
        end
      end
      lines << line
    end
    lines
  end

  def self.text(bmp, text, x, y, size = 16, tone = :paper, align = 0, maximum = nil)
    label = maximum ? fit(text, maximum, size) : text.to_s
    s = scale(size)
    w = width(label, size)
    x -= w if [1, :right, true].include?(align)
    x -= w / 2 if [2, :center].include?(align)
    atlas = image("font-#{tone}")
    label.each_char do |char|
      index = code(char) - 32
      if x >= 0 && y >= 0 && x + 5 * s <= bmp.width && y + 10 * s <= bmp.height
        bmp.stretch_blt(Rect.new(x, y, 5 * s, 10 * s), atlas,
                        Rect.new(index % 16 * 6, index / 16 * 10, 5, 10))
      end
      x += WIDTHS[index] * s
    end
    label
  end

  def self.tone(color)
    return :paper unless color && color.respond_to?(:red)
    return :gold if color.red > 180 && color.green > 140 && color.blue < 170
    return :ink if color.red < 65 && color.green < 70 && color.blue < 90
    return :muted if color.red < 210
    :paper
  end

  def self.draw_text_positions(bmp, positions)
    positions.each do |p|
      text(bmp, p[0], p[1], p[2], bmp.font.size, tone(p[4]), p[3])
    end
  end

  def self.frame(bmp, x, y, w, h, selected = false)
    return if w < 10 || h < 10
    skin = image(selected ? "tab-active" : "team")
    # Nine slices preserve one-pixel edges without stretching corners.
    border = 6
    [0, 1, 2].each do |row|
      [0, 1, 2].each do |col|
        sx = col == 0 ? 0 : col == 1 ? border : skin.width - border
        sy = row == 0 ? 0 : row == 1 ? border : skin.height - border
        sw = col == 1 ? skin.width - border * 2 : border
        sh = row == 1 ? skin.height - border * 2 : border
        dx = col == 0 ? x : col == 1 ? x + border : x + w - border
        dy = row == 0 ? y : row == 1 ? y + border : y + h - border
        dw = col == 1 ? w - border * 2 : border
        dh = row == 1 ? h - border * 2 : border
        next if dw <= 0 || dh <= 0
        bmp.stretch_blt(Rect.new(dx, dy, dw, dh), skin, Rect.new(sx, sy, sw, sh))
      end
    end
  end
end
